mapper.update:
UPDATE ctrl_payout
payout_type_id = #{payoutTypeId}, apply_amount = #{applyAmount}, apply_reason = #{applyReason}, is_nurse = #{isNurse}, status = #{status}, template_config_id = #{templateConfigId}, main_attach_id = #{mainAttachId}, process_definition_id = #{processDefinitionId}, process_instance_id = #{processInstanceId}, budget_id = #{budgetId}, budget_item_id = #{budgetItemId}, source_apply_no = #{sourceApplyNo}, contract_no = #{contractNo}, remark = #{remark},
WHERE payout_id = #{payoutId}

mapper.select:
SELECT p.payout_id, p.payout_billcode, p.bill_type, p.emp_id, p.emp_code, p.emp_name, p.dept_id, COALESCE(d.dept_name, '') AS dept_name, COALESCE(e.emp_phone, '') AS emp_phone, p.is_nurse, p.payout_type_id, p.apply_amount, p.apply_reason, p.apply_date, p.status, p.source_apply_no, p.contract_no, p.template_config_id, p.main_attach_id, p.process_definition_id, p.process_instance_id, p.budget_id, p.budget_item_id, p.remark, p.create_user, p.create_time, p.update_time FROM ctrl_payout p LEFT JOIN sys_dept d ON p.dept_id = d.dept_id LEFT JOIN sys_emp e ON p.emp_id = e.emp_id WHERE p.source_apply_no = #{sourceApplyNo} AND p.bill_type = 'PAYOUT'
AND p.payout_id != #{excludePayoutId}
LIMIT 1

SELECT p.payout_id, p.payout_billcode, p.bill_type, p.emp_id, p.emp_code, p.emp_name, p.dept_id, COALESCE(d.dept_name, '') AS dept_name, COALESCE(e.emp_phone, '') AS emp_phone, p.is_nurse, p.payout_type_id, p.apply_amount, p.apply_reason, p.apply_date, p.status, p.source_apply_no, p.contract_no, p.template_config_id, p.main_attach_id, p.process_definition_id, p.process_instance_id, p.budget_id, p.budget_item_id, p.remark, p.create_user, p.create_time, p.update_time FROM ctrl_payout p LEFT JOIN sys_dept d ON p.dept_id = d.dept_id LEFT JOIN sys_emp e ON p.emp_id = e.emp_id WHERE p.contract_no = #{contractNo} AND p.bill_type = 'PAYOUT'
AND p.payout_id != #{excludePayoutId}
LIMIT 1

SELECT p.payout_id, p.payout_billcode, p.bill_type, p.emp_id, p.emp_code, p.emp_name, p.dept_id, COALESCE(d.dept_name, '') AS dept_name, COALESCE(e.emp_phone, '') AS emp_phone, p.is_nurse, p.payout_type_id, p.apply_amount, p.apply_reason, p.apply_date, p.status,p.source_apply_no, p.template_config_id, p.main_attach_id, p.process_definition_id, p.process_instance_id, p.budget_id, p.budget_item_id, p.remark, p.create_user, p.create_time, p.update_time FROM ctrl_payout p LEFT JOIN sys_dept d ON p.dept_id = d.dept_id LEFT JOIN sys_emp e ON p.emp_id = e.emp_id
AND p.payout_billcode LIKE CONCAT('%', #{payoutBillcode}, '%')
AND p.emp_name LIKE CONCAT('%', #{empName}, '%')
AND p.payout_type_id = #{payoutTypeId}
AND p.status = #{status}
AND DATE(p.apply_date) >= #{startDate}
AND DATE(p.apply_date) <= #{endDate}
AND p.payout_billcode LIKE CONCAT(#{billTypePrefix}, '%')
ORDER BY p.create_time DESC
